import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.vLhlLNVn.js";const a="/assets/befehl-zum-geraet.CqWJEMXm.svg",s="/assets/objektbaum-ps-schreiben.DLsXBOMM.png",d="/assets/instanz-log-stufe.DpBZfPkJ.png",b=JSON.parse('{"title":"Befehle und Skripte wirken nicht","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/04.fehlerbehebung/02.befehle-wirken-nicht.md"},"headers":[],"relativePath":"de/adapter/wled/fehlerbehebung/befehle-wirken-nicht.md","filePath":"de/adapter/wled/fehlerbehebung/befehle-wirken-nicht.md","lastUpdated":null}'),o={name:"de/adapter/wled/fehlerbehebung/befehle-wirken-nicht.md"};function l(h,e,c,u,g,p){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="befehle-und-skripte-wirken-nicht" tabindex="-1">Befehle und Skripte wirken nicht <a class="header-anchor" href="#befehle-und-skripte-wirken-nicht" aria-label="Permalink to &quot;Befehle und Skripte wirken nicht&quot;">​</a></h1><p><a id="off-state-not-updated"></a></p><h2 id="warum-wird-der-ein-aus-datenpunkt-nicht-aktualisiert" tabindex="-1">Warum wird der Ein/Aus-Datenpunkt nicht aktualisiert? <a class="header-anchor" href="#warum-wird-der-ein-aus-datenpunkt-nicht-aktualisiert" aria-label="Permalink to &quot;Warum wird der Ein/Aus-Datenpunkt nicht aktualisiert?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist schaust du auf den falschen Schalter: <code>wled.0.&lt;MAC&gt;.on</code> gilt für das ganze Gerät, <code>wled.0.&lt;MAC&gt;.seg.&lt;Segment&gt;.on</code> nur für ein Segment. Schaltest du das Gerät aus, bleibt <code>seg.0.on</code> auf <code>true</code>, das ist richtig so. Steht auch der Geräteschalter still, läuft die Verbindung ohne WebSocket, und Änderungen kommen erst mit der nächsten Abfrage, standardmäßig nach bis zu 30 Sekunden.</p><h3 id="wann-der-adapter-on-nachfuhrt" tabindex="-1">Wann der Adapter on nachführt <a class="header-anchor" href="#wann-der-adapter-on-nachfuhrt" aria-label="Permalink to &quot;Wann der Adapter on nachführt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Verbindung</th><th>Wann <code>on</code> sich ändert</th></tr></thead><tbody><tr><td>WebSocket (WLED ab Firmware 0.12)</td><td>Sofort. WLED schickt jede Änderung von sich aus, egal ob aus der WLED-Oberfläche, der App, über einen Taster oder Sprachsteuerung direkt in WLED.</td></tr><tr><td>Nur HTTP</td><td>Erst bei der nächsten Abfrage, also nach höchstens „Intervall in Sekunden“ (Standard 30).</td></tr></tbody></table><p>Der Adapter schreibt einen Wert nur, wenn er sich geändert hat. Ein Auslöser, der auf „wurde aktualisiert“ wartet, sieht deshalb nichts, solange das Gerät denselben Wert meldet.</p><h3 id="so-prufst-du-es" tabindex="-1">So prüfst du es <a class="header-anchor" href="#so-prufst-du-es" aria-label="Permalink to &quot;So prüfst du es&quot;">​</a></h3><ol><li><strong>Richtiger Datenpunkt?</strong> Für das ganze Gerät nimm <code>wled.0.&lt;MAC&gt;.on</code>. Willst du wissen, ob ein einzelnes Segment leuchtet, brauchst du beide: Es leuchtet nur, wenn <code>on</code> und <code>seg.&lt;Segment&gt;.on</code> auf <code>true</code> stehen.</li><li><strong>Läuft der WebSocket?</strong> Beim Verbinden schreibt der Adapter „&lt;Gerätename&gt; connected“ ins Log. Auf Log-Stufe „debug“ siehst du bei jeder Änderung am Gerät „Websocket WLED message received for 192.168.x.y“. Steht im Log „does not support websocket … Switching to http-APi“, ist die Firmware zu alt, dann hilft ein WLED-Update.</li><li><strong>Ist das Gerät online?</strong> Prüf <code>wled.0.&lt;MAC&gt;._info._online</code>. Solange das Gerät nicht verbunden ist, bekommt der Adapter keine Änderungen.</li><li><strong>Steht der Wert auf <code>ack=false</code>?</strong> Dann ist ein Befehl aus ioBroker nicht beim Gerät angekommen, siehe <a href="#script-not-ps-wled-ignores">Skript setzt ps oder on nicht</a>.</li></ol><h3 id="alexa-und-web-oberflache" tabindex="-1">Alexa und Web-Oberfläche <a class="header-anchor" href="#alexa-und-web-oberflache" aria-label="Permalink to &quot;Alexa und Web-Oberfläche&quot;">​</a></h3><ul><li><strong>Alexa direkt mit WLED verbunden</strong> (WLED meldet sich selbst als Lampe): Das ist eine Änderung am Gerät. Mit WebSocket ist <code>on</code> sofort richtig, sonst nach der nächsten Abfrage.</li><li><strong>Alexa über den iot-Adapter</strong>: Das ist ein Befehl aus ioBroker. Er wird erst mit <code>ack=false</code> geschrieben und vom WLED-Adapter an das Gerät geschickt. Bleibt <code>ack=false</code> stehen, kam er nicht an.</li><li><strong>WLED-Oberfläche und App</strong>: immer eine Änderung am Gerät, wie bei Alexa direkt.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Bis v0.9.2</strong> setzt der Adapter <code>on</code> auf <code>false</code> und <code>bri</code> auf <code>0</code>, wenn ein Gerät offline geht, und beim Adapterstart. <code>on</code> zeigt dann <code>false</code>, obwohl das Licht vielleicht noch leuchtet. <strong>Ab v0.9.3:</strong> <code>on</code> und <code>bri</code> behalten ihren letzten Wert, bis das Gerät wieder meldet (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p></div><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erste-steuerung#state-use-switch-off-whole">Welchen Datenpunkt nehme ich zum Ein- und Ausschalten</a> · <a href="#some-leds-stay-after-switching">Warum bleiben nach dem Ausschalten einige LEDs an</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#states-only-updated-after-30">Zustände erst nach 30 Sekunden aktualisiert</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät online ist</a></p><p><a id="script-not-ps-wled-ignores"></a></p><h2 id="warum-setzt-mein-skript-ps-oder-on-nicht-oder-wled-ignoriert-die-befehle" tabindex="-1">Warum setzt mein Skript ps oder on nicht, oder WLED ignoriert die Befehle? <a class="header-anchor" href="#warum-setzt-mein-skript-ps-oder-on-nicht-oder-wled-ignoriert-die-befehle" aria-label="Permalink to &quot;Warum setzt mein Skript ps oder on nicht, oder WLED ignoriert die Befehle?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist liegt es an einer von fünf Ursachen: Der Wert wurde als Bestätigung (<code>ack=true</code>) statt als Steuerbefehl geschrieben, das Gerät war für den Adapter gerade offline, dasselbe Preset war schon aktiv, der Datentyp stimmt nicht, oder es kamen zu viele Befehle zu schnell hintereinander. Die Checkliste unten führt dich der Reihe nach durch.</p><p>So kommt ein Befehl beim Gerät an: Der Adapter reagiert nur auf Schreibzugriffe mit <code>ack=false</code>. Er baut daraus einen JSON-Befehl, zum Beispiel <code>{&quot;ps&quot;:3}</code> oder <code>{&quot;on&quot;:true}</code>, und schickt ihn sofort ab: über die WebSocket-Verbindung, wenn sie steht, sonst per HTTP an <code>http://192.168.x.y/json</code>. Es gibt keine Warteschlange und keine Wiederholung.</p><p><img src="'+a+'" alt="Ablauf eines Befehls: Nur Werte mit ack=false werden gesendet, nur an ein verbundenes Gerät, per WebSocket oder HTTP. Was nicht ankommt, ist verloren."></p><h3 id="checkliste" tabindex="-1">Checkliste <a class="header-anchor" href="#checkliste" aria-label="Permalink to &quot;Checkliste&quot;">​</a></h3><ol><li><strong>Steuern statt aktualisieren.</strong> In Blockly muss der Block „steuere“ sein, nicht „aktualisiere“. In JavaScript schreibst du <code>setState(id, wert)</code> ohne <code>true</code> als drittes Argument. Ein Wert mit <code>ack=true</code> gilt als Rückmeldung vom Gerät und wird nicht gesendet.</li></ol><ol start="2"><li><strong>Von Hand testen.</strong> Schreib denselben Wert im Objektbaum des Admins in den Datenpunkt. Reagiert WLED darauf, liegt der Fehler im Skript, zum Beispiel an verschachtelten Auslösern oder einer falschen Objekt-ID. Die IDs der Geräte sind ihre MAC-Adressen, sie ändern sich nicht, wenn du das Gerät umbenennst.</li></ol><p><img src="'+s+'" alt="Admin 8.3, Reiter „Objekte“: Für wled.0.MAC.ps ist der Dialog „Wert schreiben“ offen, im Feld „Wert“ steht 5, der Haken „Bestätigt“ ist nicht gesetzt. So geht der Wert als Steuerbefehl an das Gerät."></p><ol start="3"><li><strong>Ist das Gerät online?</strong> Schau auf <code>wled.0.&lt;MAC&gt;._info._online</code>. Befehle an ein Gerät, das nicht erreichbar ist, gehen verloren. Der Adapter puffert nichts und wiederholt nichts. <ul><li><strong>Bis v0.9.2:</strong> Im Log steht ein Fehler „Sending command to WLED device … failed with error …“. Ist das Gerät dem Adapter gerade gar nicht bekannt, steht dort stattdessen ein TypeError, der auch an Sentry gemeldet wird.</li><li><strong>Ab v0.9.3:</strong> Der Adapter verwirft den Befehl mit der Warnung <code>Device &lt;MAC&gt; (192.168.x.y) is offline, command for … discarded</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>).</li></ul></li></ol><ol start="4"><li><strong>Zu schnell nach dem Einschalten?</strong> Bekommt WLED gerade erst Strom, zum Beispiel über eine Zwischensteckdose, ist es erst nach einigen Sekunden im WLAN erreichbar. Befehle davor gehen verloren. <ul><li><strong>Ab v0.9.3</strong> kommt hinzu: Der Adapter sendet nur an Geräte, die er als verbunden kennt (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>). Dass ein Gerät wieder da ist, merkt er erst bei der nächsten Prüfung. Die läuft standardmäßig alle 30 Sekunden („Intervall in Sekunden“, ab v0.10.0 „Abfrage-Intervall“). War das Gerät länger aus, prüft er seltener: Die Abstände verdoppeln sich bis höchstens 10 Minuten, und nach 5 Fehlversuchen („Maximale Wiederholungsversuche“) nur noch einmal pro Stunde. Bis dahin verwirft er Befehle.</li><li><strong>Ab v0.10.0:</strong> Kommt ein Befehl für ein Gerät, das als offline gilt, versucht der Adapter sofort, es zu erreichen. Ist es inzwischen wieder im WLAN, geht der Befehl gleich raus, ohne dass du auf die nächste Prüfung wartest (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/939" target="_blank" rel="noreferrer">#939</a>). Nur wenn es noch nicht antwortet, verwirft er den Befehl wie oben. Einen neuen Versuch startet ein Befehl frühestens 5 Sekunden nach dem letzten.</li><li>Bis v0.9.3 und für Befehle in den ersten Sekunden nach dem Einschalten gilt: Lass dein Skript warten, bis <code>wled.0.&lt;MAC&gt;._info._online</code> auf <code>true</code> geht, und schick den Befehl erst dann.</li></ul></li></ol><ol start="5"><li><strong>Dasselbe Preset schon aktiv?</strong> Zeigt <code>ps</code> bereits die Nummer, die du schreibst, lädt WLED das Preset nicht noch einmal. Das passiert auch, wenn du das Licht zwischendurch über <code>on</code> ausgeschaltet hast. Schick dann <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> an <code>wled.0.&lt;MAC&gt;.action</code>.</li></ol><ol start="6"><li><strong>Passt der Datentyp?</strong> <code>on</code> erwartet <code>true</code> oder <code>false</code>, <code>ps</code> eine Zahl. Schreibst du <code>on</code> als Text, macht WLED etwas anderes als gedacht: Ein Text, der mit <code>t</code> beginnt (also auch <code>&quot;true&quot;</code>), schaltet um, und <code>&quot;false&quot;</code> als Text bewirkt gar nichts. ioBroker meldet einen falschen Datentyp zusätzlich als Warnung im Log.</li></ol><ol start="7"><li><strong>Zu viele Befehle hintereinander?</strong> Jeder geänderte Datenpunkt ist ein eigener Befehl. Schreibt dein Skript <code>on</code>, <code>bri</code>, Farbe und <code>ps</code> direkt nacheinander, kann WLED Befehle verlieren oder mit Zeitüberschreitung antworten. Fass zusammengehörende Werte in einem JSON-Befehl über <code>action</code> zusammen, zum Beispiel <code>{&quot;on&quot;:true,&quot;bri&quot;:128,&quot;ps&quot;:3}</code>, oder leg sie gleich in einem Preset ab und setz nur <code>ps</code>. Wenn es einzelne Befehle sein müssen, lass zwischen ihnen eine kurze Pause.</li></ol><p><strong>Ab v0.10.0:</strong> Der Adapter bündelt selbst: Änderungen am selben Gerät, die innerhalb von 50 ms aufeinander folgen, schickt er als einen Befehl (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/926" target="_blank" rel="noreferrer">#926</a>). Die Wartezeit stellst du in den Instanzeinstellungen unter „Wartezeit zum Bündeln von Befehlen je Gerät“ ein, 0 schaltet das Bündeln ab. Mehr dazu unter <a href="#several-commands-quick-succession-lead">Mehrere Befehle führen zu ETIMEDOUT</a>.</p><ol start="8"><li><strong>Rückmeldung über WebSocket.</strong> Läuft die Verbindung über WebSocket, setzt der Adapter <strong>bis v0.9.2</strong> selbst kein <code>ack=true</code> und meldet auch keinen Sendefehler. Das <code>ack</code> kommt erst, wenn WLED seinen neuen Zustand meldet. Bleibt ein Wert auf <code>ack=false</code>, ist der Befehl wahrscheinlich nicht angekommen. <strong>Ab v0.9.3:</strong> Der Adapter setzt <code>ack=true</code>, sobald der Befehl gesendet ist, und schreibt eine Warnung „Sending command for … failed“ ins Log, wenn das Senden scheitert (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>).</li></ol><ol start="9"><li><strong>Segment-Befehle.</strong> Setzt du einen Wert in einem Segment, etwa <code>wled.0.&lt;MAC&gt;.seg.0.fx</code>, geht der Befehl nur an dieses Segment. Prüf, ob du das richtige Segment erwischt hast und ob es eingeschaltet ist.</li></ol><ol start="10"><li><strong>Debug-Log ansehen.</strong> Stell die Instanz auf Log-Stufe „debug“: Im Reiter „Instanzen“ klappst du die Zeile von <code>wled.0</code> auf, klickst neben der Log-Stufe (<code>info</code>) auf den Stift und wählst „Debug“. Bei jedem Befehl erscheint dann „Sending state change by websocket …“ oder „Sending state change by http-API …“ mit dem gesendeten JSON. Fehlt die Zeile, ist der Befehl gar nicht beim Adapter angekommen.</li></ol><p><img src="'+d+'" alt="Admin 8.3, Reiter „Instanzen“: Die Zeile von wled.0 ist aufgeklappt, darüber der Dialog „Die Protokollebene für wled.0 bearbeiten“ mit der Protokollstufe „Debug“."></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Liest dein Skript <code>on</code>, beachte: <strong>Bis v0.9.2</strong> setzt der Adapter <code>on</code> auf <code>false</code> und <code>bri</code> auf <code>0</code>, wenn ein Gerät offline geht, und beim Adapterstart. <strong>Ab v0.9.3:</strong> Beide behalten ihren letzten Wert, die echten Werte kommen beim Wiederverbinden vom Gerät (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/effekte-und-presets#switch-wled-presets-via-ps">Presets per Datenpunkt ps schalten</a> · <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a> · <a href="#several-commands-quick-succession-lead">Mehrere Befehle führen zu ETIMEDOUT</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät online ist</a> · <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Wiederholungen bei Offline-Geräten</a> · <a href="./../referenz/log-meldungen#warnings-about-wrong-data-type">Warnungen zum falschen Datentyp</a></p><p><a id="several-commands-quick-succession-lead"></a></p><h2 id="warum-fuhren-mehrere-befehle-kurz-hintereinander-zu-etimedout" tabindex="-1">Warum führen mehrere Befehle kurz hintereinander zu ETIMEDOUT? <a class="header-anchor" href="#warum-fuhren-mehrere-befehle-kurz-hintereinander-zu-etimedout" aria-label="Permalink to &quot;Warum führen mehrere Befehle kurz hintereinander zu ETIMEDOUT?&quot;">​</a></h2><p><strong>Kurz:</strong> Jeder Datenpunkt, den dein Skript schreibt, ist ein eigener Befehl an das Gerät. Ohne WebSocket wird daraus je eine HTTP-Anfrage, und viele Anfragen auf einmal beantwortet WLED nicht rechtzeitig. Fass die Werte eines Schritts in einem JSON-Befehl über <code>wled.0.&lt;MAC&gt;.action</code> zusammen, statt <code>on</code>, <code>bri</code>, Farbe und Effekt einzeln zu schreiben.</p><p>Im Log steht dann zum Beispiel <code>Sending command to WLED device + http://192.168.x.y/json failed with error Error: connect ETIMEDOUT</code>. <strong>Bis v0.9.2</strong> ist das ein Fehler, <strong>ab v0.9.3</strong> eine Warnung, ohne das <code>+</code> im Text.</p><h3 id="warum-das-passiert" tabindex="-1">Warum das passiert <a class="header-anchor" href="#warum-das-passiert" aria-label="Permalink to &quot;Warum das passiert&quot;">​</a></h3><p>Der Adapter hat im Grundstand v0.9.2 keine Warteschlange. Jeder Schreibzugriff mit <code>ack=false</code> wird sofort und unabhängig von den anderen abgeschickt. Schreibt ein Skript vier Datenpunkte direkt hintereinander, gehen vier Anfragen fast gleichzeitig an das Gerät. Über WebSocket sind es vier Nachrichten auf derselben Verbindung, über HTTP vier eigene Anfragen. Kommt auf eine davon nicht rechtzeitig eine Antwort, meldet die Verbindung <code>ETIMEDOUT</code>, und dieser Befehl ist verloren.</p><h3 id="so-vermeidest-du-es" tabindex="-1">So vermeidest du es <a class="header-anchor" href="#so-vermeidest-du-es" aria-label="Permalink to &quot;So vermeidest du es&quot;">​</a></h3><ol><li><strong>Ein Befehl statt vieler.</strong> Schick alles, was zusammengehört, als einen Text an <code>wled.0.&lt;MAC&gt;.action</code>:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bri&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">180</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;seg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;col&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]}}</span></span></code></pre></div>In JavaScript: <code>setState(&#39;wled.0.&lt;MAC&gt;.action&#39;, JSON.stringify({ on: true, bri: 180, seg: { id: 0, fx: 0, col: [[255, 120, 0]] } }));</code>.</li><li><strong>Oder ein Preset.</strong> Leg den Zustand in WLED als Preset ab und setz nur <code>ps</code>.</li><li><strong>Abstand zwischen Einzelbefehlen.</strong> Müssen es einzelne Befehle sein, lass dazwischen eine Pause, zum Beispiel mit <code>await wait(200);</code> im JavaScript oder „steuere … mit Verzögerung“ in Blockly. Ein paar hundert Millisekunden reichen in der Regel.</li><li><strong>WebSocket prüfen.</strong> Schreibt der Adapter beim Verbinden „does not support websocket … Switching to http-APi“ ins Log, läuft alles über HTTP. Ein Update der WLED-Firmware auf 0.12 oder neuer behebt das.</li></ol><p>Wie du den kompletten JSON-Befehl aufbaust, steht unter <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a>.</p><h3 id="ab-v0-10-0-der-adapter-bundelt-selbst" tabindex="-1">Ab v0.10.0: Der Adapter bündelt selbst <a class="header-anchor" href="#ab-v0-10-0-der-adapter-bundelt-selbst" aria-label="Permalink to &quot;Ab v0.10.0: Der Adapter bündelt selbst&quot;">​</a></h3><p><strong>Ab v0.10.0:</strong> Befehle an dasselbe Gerät, die innerhalb kurzer Zeit aufeinander folgen, fasst der Adapter zu einem Befehl zusammen (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/926" target="_blank" rel="noreferrer">#926</a>). Mehrere <code>setState()</code> direkt hintereinander gehen dann als ein Befehl raus.</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wo</th><th>Wirkung</th></tr></thead><tbody><tr><td>„Wartezeit zum Bündeln von Befehlen je Gerät“ (<code>bundleDelay</code>)</td><td>Instanzeinstellungen, Reiter „Einstellungen“, Abschnitt „Befehle“</td><td>So lange wartet der Adapter auf weitere Befehle. Standard 50 ms, höchstens 1000 ms, <code>0</code> schaltet das Bündeln für alle Geräte aus.</td></tr><tr><td><code>wled.0.&lt;MAC&gt;.bundleCommands</code></td><td>Objektbaum, Skript</td><td><code>false</code> schaltet das Bündeln für dieses Gerät aus, <code>true</code> wieder ein. Lässt sich zur Laufzeit umschalten.</td></tr><tr><td>„Kurz aufeinander folgende Befehle bündeln“</td><td>Device Manager (in Admin 8.3 „Konfig-Manager“, in älteren Admins „Geräte“), „Gerät bearbeiten“</td><td>Dasselbe wie <code>bundleCommands</code>.</td></tr></tbody></table><p>Schalte das Bündeln für ein Gerät aus, wenn jeder Befehl einzeln ankommen muss, zum Beispiel für einen Party-Modus mit schnellen Farbwechseln. Zwei Befehle, die denselben Wert relativ ändern (etwa zweimal <code>&quot;t&quot;</code> zum Umschalten), schickt der Adapter auch beim Bündeln nacheinander, damit keiner verloren geht. Verschiedene Geräte bündelt er unabhängig voneinander.</p><p><strong>Siehe auch:</strong> <a href="#script-not-ps-wled-ignores">Skript setzt ps oder on nicht</a> · <a href="./../anleitungen/skripte#control-wled-javascript-periodically-step">WLED per JavaScript schrittweise steuern</a> · <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a></p><p><a id="ps-jump-1-not-show"></a></p><h2 id="warum-springt-ps-auf-1-oder-zeigt-nicht-das-gewahlte-preset" tabindex="-1">Warum springt ps auf -1 oder zeigt nicht das gewählte Preset? <a class="header-anchor" href="#warum-springt-ps-auf-1-oder-zeigt-nicht-das-gewahlte-preset" aria-label="Permalink to &quot;Warum springt ps auf -1 oder zeigt nicht das gewählte Preset?&quot;">​</a></h2><p><strong>Kurz:</strong> <code>ps</code> zeigt immer, was WLED als aktives Preset meldet. Der Adapter rechnet daran nichts um und setzt den Wert nie selbst. <code>-1</code> heißt: Gerade ist kein Preset aktiv, weil sich seit dem Laden etwas geändert hat, zum Beispiel Farbe, Effekt oder Helligkeit. Das ist normal und kein Fehler.</p><p>WLED merkt sich ein Preset nur so lange als aktiv, wie der Zustand dem gespeicherten entspricht. Jede Änderung danach, aus der WLED-Oberfläche, der App, über einen anderen Datenpunkt oder per Sync von einem anderen WLED-Gerät, beendet das. WLED meldet dann <code>-1</code>, und der Adapter schreibt <code>-1</code> in <code>ps</code>.</p><h3 id="wann-1-normal-ist" tabindex="-1">Wann -1 normal ist <a class="header-anchor" href="#wann-1-normal-ist" aria-label="Permalink to &quot;Wann -1 normal ist&quot;">​</a></h3><ul><li>Du hast nach dem Preset Farbe, Helligkeit, Effekt oder ein Segment geändert.</li><li>Dein Skript schreibt direkt nach <code>ps</code> noch andere Datenpunkte. <code>ps</code> zeigt dann kurz die Nummer und springt auf <code>-1</code>.</li><li>Ein anderes WLED-Gerät schickt per UDP-Sync seinen Zustand.</li><li>Du hast das Licht ohne Preset eingestellt, zum Beispiel nach einem Neustart ohne Start-Preset.</li></ul><h3 id="wann-ps-nicht-das-gewahlte-preset-zeigt" tabindex="-1">Wann ps nicht das gewählte Preset zeigt <a class="header-anchor" href="#wann-ps-nicht-das-gewahlte-preset-zeigt" aria-label="Permalink to &quot;Wann ps nicht das gewählte Preset zeigt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was du siehst</th><th>Ursache</th><th>Was du tust</th></tr></thead><tbody><tr><td><code>ps</code> springt kurz nach dem Setzen auf <code>-1</code></td><td>Danach hat sich noch etwas geändert, siehe oben</td><td>Weitere Werte in das Preset aufnehmen statt sie danach zu schreiben, oder alles in einem Befehl über <code>action</code> schicken</td></tr><tr><td><code>ps</code> bleibt auf der alten Nummer</td><td>Das Preset gibt es in WLED nicht, oder der Befehl kam nicht an</td><td>Nummer in der WLED-Oberfläche prüfen; Checkliste unter <a href="#script-not-ps-wled-ignores">Skript setzt ps oder on nicht</a></td></tr><tr><td>Erneutes Schreiben derselben Nummer bewirkt nichts</td><td>WLED lädt das aktive Preset nicht noch einmal</td><td><code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> an <code>wled.0.&lt;MAC&gt;.action</code> schicken</td></tr><tr><td>Während einer Playlist wechselt <code>ps</code> von selbst</td><td><code>ps</code> zeigt das gerade laufende Preset aus der Playlist, <code>pl</code> die Playlist</td><td>Nichts, das ist so gewollt</td></tr><tr><td><code>ps</code> bleibt <code>ack=false</code></td><td>Befehl nicht beim Gerät angekommen</td><td>Checkliste unter <a href="#script-not-ps-wled-ignores">Skript setzt ps oder on nicht</a></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Das Verhalten hängt von der WLED-Firmware ab. Mit einer Beta von WLED 0.14 sprang <code>ps</code> schon beim Ausschalten auf <code>-1</code> und beim Einschalten nicht zurück, mit 0.13 nicht (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/478" target="_blank" rel="noreferrer">#478</a>). Mit WLED 0.15 bleibt die Nummer beim Aus- und Einschalten über <code>on</code> stehen. Vergleich im Zweifel mit der WLED-Oberfläche: Zeigt sie dasselbe wie <code>ps</code>, arbeitet der Adapter richtig.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Willst du im Skript wissen, welches Preset du zuletzt gesetzt hast, auch wenn WLED inzwischen <code>-1</code> meldet, merk dir die Nummer in einem eigenen Datenpunkt unter <code>0_userdata.0</code>.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/effekte-und-presets#switch-wled-presets-via-ps">Presets per Datenpunkt ps schalten</a> · <a href="./../anleitungen/effekte-und-presets#start-wled-playlist-through-adapter">Playlist starten</a> · <a href="./../anleitungen/skripte#save-state-restore-after-animation">Zustand speichern und wiederherstellen</a></p><p><a id="some-leds-stay-after-switching"></a></p><h2 id="warum-bleiben-nach-dem-ausschalten-einige-leds-an" tabindex="-1">Warum bleiben nach dem Ausschalten einige LEDs an? <a class="header-anchor" href="#warum-bleiben-nach-dem-ausschalten-einige-leds-an" aria-label="Permalink to &quot;Warum bleiben nach dem Ausschalten einige LEDs an?&quot;">​</a></h2><p><strong>Kurz:</strong> Prüf zuerst, welchen Schalter du benutzt hast. <code>wled.0.&lt;MAC&gt;.seg.&lt;Segment&gt;.on</code> schaltet nur dieses eine Segment aus, die anderen Segmente leuchten weiter. Das ganze Gerät schaltest du mit <code>wled.0.&lt;MAC&gt;.on</code> aus. Bleiben auch dann LEDs an, empfängt WLED meist Echtzeitdaten von einem anderen Programm, oder es liegt an der Hardware.</p><h3 id="gerat-oder-segment" tabindex="-1">Gerät oder Segment? <a class="header-anchor" href="#gerat-oder-segment" aria-label="Permalink to &quot;Gerät oder Segment?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Befehl an WLED</th><th>Wirkung</th></tr></thead><tbody><tr><td><code>wled.0.&lt;MAC&gt;.on</code></td><td><code>{&quot;on&quot;:false}</code></td><td>Das ganze Gerät ist aus, alle Segmente dunkel.</td></tr><tr><td><code>wled.0.&lt;MAC&gt;.seg.1.on</code></td><td><code>{&quot;seg&quot;:{&quot;id&quot;:1,&quot;on&quot;:false}}</code></td><td>Nur Segment 1 ist aus. Alle anderen Segmente bleiben, wie sie sind.</td></tr></tbody></table><p>Ein Segment, das du über <code>seg.&lt;Segment&gt;.on</code> ausgeschaltet hast, bleibt auch aus, wenn du das Gerät danach wieder über <code>on</code> einschaltest. Schalte es dann gezielt wieder ein.</p><h3 id="alle-segmente-auf-einmal-schalten" tabindex="-1">Alle Segmente auf einmal schalten <a class="header-anchor" href="#alle-segmente-auf-einmal-schalten" aria-label="Permalink to &quot;Alle Segmente auf einmal schalten&quot;">​</a></h3><p>Willst du alle Segmente einzeln aus- oder einschalten, schick ihre Nummern als Liste an <code>wled.0.&lt;MAC&gt;.action</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;seg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}</span></span></code></pre></div><p>Ein <code>seg</code>-Befehl ohne <code>id</code>, also <code>{&quot;seg&quot;:{&quot;on&quot;:false}}</code>, wirkt nur auf die Segmente, die in WLED gerade ausgewählt sind, nicht auf alle. Gib die Nummern deshalb immer an.</p><h3 id="wenn-trotz-on-false-leds-leuchten" tabindex="-1">Wenn trotz on = false LEDs leuchten <a class="header-anchor" href="#wenn-trotz-on-false-leds-leuchten" aria-label="Permalink to &quot;Wenn trotz on = false LEDs leuchten&quot;">​</a></h3><ul><li><strong>Echtzeitdaten:</strong> Sendet ein anderes Programm Lichtdaten an WLED, zum Beispiel Hyperion, xLights oder ein Gerät per E1.31 oder UDP, zeigt WLED diese Daten an. <code>wled.0.&lt;MAC&gt;._info.live</code> steht dann auf <code>true</code>, <code>_info.lm</code> nennt die Art der Daten und <code>_info.lip</code> die Adresse des Senders. Stopp den Sender oder schreib <code>1</code> in <code>wled.0.&lt;MAC&gt;.lor</code>: Dann ignoriert WLED die Echtzeitdaten, bis sie enden. Mit <code>2</code> gilt das bis zum nächsten Neustart des Geräts.</li><li><strong>UDP-Sync:</strong> Schaltet ein anderes WLED-Gerät per Sync dieses wieder ein, prüf die Einstellungen unter <code>wled.0.&lt;MAC&gt;.udpn</code>.</li><li><strong>Hardware:</strong> Bleiben LEDs an, obwohl WLED aus meldet und keine Echtzeitdaten kommen, liegt es nicht am Adapter. Der Adapter schickt nur <code>{&quot;on&quot;:false}</code>. Prüf das Gerät dann in der WLED-Oberfläche und mit der WLED-Dokumentation.</li></ul><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erste-steuerung#state-use-switch-off-whole">Welchen Datenpunkt nehme ich zum Ein- und Ausschalten</a> · <a href="#off-state-not-updated">Warum wird der Ein/Aus-Datenpunkt nicht aktualisiert</a> · <a href="./../referenz/datenpunkte#use-udp-sync-state-udpn">UDP-Sync über udpn</a> · <a href="./segmente-und-synchronisation#one-wled-device-take-over">Ein WLED-Gerät übernimmt die Einstellungen eines anderen</a></p><p><a id="cct-state-have-no-effect"></a></p><h2 id="warum-hat-der-datenpunkt-cct-keine-wirkung" tabindex="-1">Warum hat der Datenpunkt cct keine Wirkung? <a class="header-anchor" href="#warum-hat-der-datenpunkt-cct-keine-wirkung" aria-label="Permalink to &quot;Warum hat der Datenpunkt cct keine Wirkung?&quot;">​</a></h2><p><strong>Kurz:</strong> <code>seg.&lt;Segment&gt;.cct</code> stellt die Mischung aus warmweißen und kaltweißen LEDs ein. Das wirkt nur bei LED-Typen mit getrennten Kanälen für Warm- und Kaltweiß, zum Beispiel analogen CCT-Streifen mit zwei oder fünf Kanälen oder digitalen Typen wie WS2805 und FW1906. Auf normalen adressierbaren RGB- oder RGBW-Streifen (WS2812, WS2815, SK6812) hat <code>cct</code> keine Wirkung, dort änderst du die Farbe.</p><p>Der Adapter reicht den Wert nur an das Segment weiter, als <code>{&quot;seg&quot;:{&quot;id&quot;:0,&quot;cct&quot;:…}}</code>. Was daraus wird, entscheidet WLED anhand des LED-Typs, der unter „Config“ → „LED Preferences“ eingestellt ist.</p><h3 id="so-prufst-du-ob-dein-gerat-cct-kann" tabindex="-1">So prüfst du, ob dein Gerät cct kann <a class="header-anchor" href="#so-prufst-du-ob-dein-gerat-cct-kann" aria-label="Permalink to &quot;So prüfst du, ob dein Gerät cct kann&quot;">​</a></h3><ol><li>Sieh dir <code>wled.0.&lt;MAC&gt;._info.leds.lc</code> an. Der Wert ist eine Summe: <code>1</code> steht für RGB, <code>2</code> für einen Weißkanal, <code>4</code> für Farbtemperatur (CCT). Nur wenn die <code>4</code> enthalten ist (also bei <code>4</code>, <code>5</code>, <code>6</code> oder <code>7</code>), wirkt <code>cct</code>.</li><li>In der WLED-Oberfläche erscheint dann ein eigener Regler für die Weißtemperatur.</li></ol><h3 id="welche-werte-cct-versteht" tabindex="-1">Welche Werte cct versteht <a class="header-anchor" href="#welche-werte-cct-versteht" aria-label="Permalink to &quot;Welche Werte cct versteht&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Wert</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>0</code> bis <code>255</code></td><td><code>0</code> ist ganz warmweiß, <code>255</code> ganz kaltweiß</td></tr><tr><td><code>1900</code> bis <code>10091</code></td><td>Farbtemperatur in Kelvin, WLED rechnet sie in 0 bis 255 um</td></tr></tbody></table><h3 id="was-du-bei-rgb-und-rgbw-streifen-stattdessen-tust" tabindex="-1">Was du bei RGB- und RGBW-Streifen stattdessen tust <a class="header-anchor" href="#was-du-bei-rgb-und-rgbw-streifen-stattdessen-tust" aria-label="Permalink to &quot;Was du bei RGB- und RGBW-Streifen stattdessen tust&quot;">​</a></h3><p>Der Farbtemperatur-Regler im Farbwähler der WLED-Oberfläche ändert bei diesen Streifen die Farbe selbst. In ioBroker siehst du das an <code>seg.&lt;Segment&gt;.col.0</code> und <code>col.0_HEX</code>. Willst du aus ioBroker ein wärmeres oder kälteres Weiß, schreib eine passende Farbe, zum Beispiel <code>[255,180,110]</code> für Warmweiß. Bei RGBW-Streifen steuerst du den Weißkanal über die vierte Zahl der Farbe.</p><p>Wie du Farben und den Weißkanal schreibst, steht unter <a href="./../anleitungen/farbe#write-colour-wled-script-blockly">Farbe per Skript schreiben</a> und <a href="./../anleitungen/farbe#control-white-channel-rgbw-sk6812">Weißkanal steuern</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Unter <code>_info.leds</code> gibt es ebenfalls einen Datenpunkt <code>cct</code>. Er zeigt nur an, ob das Gerät Farbtemperatur kann, und der Adapter legt ihn wegen des gleichen Namens als beschreibbar an. Schreiben bewirkt dort nichts. Steuern kannst du nur <code>seg.&lt;Segment&gt;.cct</code>.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/farbe#control-white-channel-rgbw-sk6812">Weißkanal steuern</a> · <a href="./../referenz/datenpunkte#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte</a></p>',85)])])}const m=t(o,[["render",l]]);export{b as __pageData,m as default};
